func qualDRWACandidateFixtureDir(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	for name, fixture := range qualDRWACandidateFixtures {
		body := []byte(fixture.body)
		require.Equal(t, fixture.sha256, fmt.Sprintf("%x", sha256.Sum256(body)), name)
		path := filepath.Join(dir, name)
		require.NoError(t, os.MkdirAll(filepath.Dir(path), 0700))
		require.NoError(t, os.WriteFile(path, body, 0600))
	}
	// The repository already owns these exact public WASM inputs. Reuse them
	// rather than embedding a second binary copy. No execution occurs here.
	for name, expected := range map[string]string{
		"delegation.wasm": "5f27d31e8dfccc2eca10c773d5a713ff60959e3a608e4cf7a9d4fc836125e02c",
		"dns.wasm":        "25d0d0ae4c9c1dacf58b6a0266b7ae80a97b8471f99bb0c1ffff2109dfb966f3",
	} {
		body, err := os.ReadFile(filepath.Join("..", "..", "cmd", "node", "config", "genesisContracts", name))
		require.NoError(t, err)
		require.Equal(t, expected, fmt.Sprintf("%x", sha256.Sum256(body)), name)
		path := filepath.Join(dir, "genesisContracts", name)
		require.NoError(t, os.MkdirAll(filepath.Dir(path), 0700))
		require.NoError(t, os.WriteFile(path, body, 0600))
	}
	// Candidate03 JSON contains installation-specific absolute filenames.
	// Preserve every other field and relocate ONLY these test-input locators.
	var contracts []map[string]interface{}
	require.NoError(t, json.Unmarshal([]byte(qualDRWACandidateFixtures["genesisSmartContracts.json"].body), &contracts))
	require.Len(t, contracts, 2)
	for _, contract := range contracts {
		original, ok := contract["filename"].(string)
		require.True(t, ok)
		name := filepath.Base(original)
		require.Contains(t, []string{"delegation.wasm", "dns.wasm"}, name)
		require.True(t, strings.HasSuffix(original, "/genesisContracts/"+name))
		contract["filename"] = filepath.Join(dir, "genesisContracts", name)
	}
	body, err := json.Marshal(contracts)
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(dir, "genesisSmartContracts.json"), body, 0600))
	return dir
}
